const char *posture_state_id(posture_state_t state) {
    switch (state) {
    case POSTURE_STATE_OFF: return "posture.Off";
    case POSTURE_STATE_CALIBRATING: return "posture.Calibrating";
    case POSTURE_STATE_MONITORING: return "posture.Monitoring";
    case POSTURE_STATE_SLOUCHING: return "posture.Slouching";
    case POSTURE_STATE_NUDGING: return "posture.Nudging";
    }
    return "?";
}

const char *posture_event_name(posture_event_t event) {
    switch (event) {
    case POSTURE_EV_POWER_ON: return "POWER_ON";
    case POSTURE_EV_POWER_OFF: return "POWER_OFF";
    case POSTURE_EV_CALIBRATED: return "CALIBRATED";
    case POSTURE_EV_SLOUCH: return "SLOUCH";
    case POSTURE_EV_UPRIGHT: return "UPRIGHT";
    case POSTURE_EV_GRACE_ELAPSED: return "GRACE_ELAPSED";
    case POSTURE_EV_NUDGE_DONE: return "NUDGE_DONE";
    case POSTURE_EV_FAULT: return "FAULT";
    }
    return "?";
}

bool posture_event_from_name(const char *name, posture_event_t *event) {
    for (int i = 0; i < POSTURE_EVENT_COUNT; i++)
        if (!strcmp(posture_event_name((posture_event_t)i), name)) {
            *event = (posture_event_t)i;
            return true;
        }
    return false;
}

