static bool poll_services(posture_machine_t *m, posture_safe_hal_t *hal, posture_event_t *out) {
    switch (m->state) {
    case POSTURE_STATE_OFF:
        return false;
    case POSTURE_STATE_CALIBRATING:
        return false;
    case POSTURE_STATE_MONITORING:
        if (posture_imu_posture_poll(hal, out)) {
            switch (*out) {
            case POSTURE_EV_SLOUCH:
            case POSTURE_EV_UPRIGHT:
                return true;
            case POSTURE_EV_POWER_ON:
            case POSTURE_EV_POWER_OFF:
            case POSTURE_EV_CALIBRATED:
            case POSTURE_EV_GRACE_ELAPSED:
            case POSTURE_EV_NUDGE_DONE:
            case POSTURE_EV_FAULT:
                posture_hal_log(hal, "imu_posture emitted an event it does not declare in 'emits'");
                break;
            }
        }
        return false;
    case POSTURE_STATE_SLOUCHING:
        if (posture_imu_posture_poll(hal, out)) {
            switch (*out) {
            case POSTURE_EV_SLOUCH:
            case POSTURE_EV_UPRIGHT:
                return true;
            case POSTURE_EV_POWER_ON:
            case POSTURE_EV_POWER_OFF:
            case POSTURE_EV_CALIBRATED:
            case POSTURE_EV_GRACE_ELAPSED:
            case POSTURE_EV_NUDGE_DONE:
            case POSTURE_EV_FAULT:
                posture_hal_log(hal, "imu_posture emitted an event it does not declare in 'emits'");
                break;
            }
        }
        return false;
    case POSTURE_STATE_NUDGING:
        if (posture_imu_posture_poll(hal, out)) {
            switch (*out) {
            case POSTURE_EV_SLOUCH:
            case POSTURE_EV_UPRIGHT:
                return true;
            case POSTURE_EV_POWER_ON:
            case POSTURE_EV_POWER_OFF:
            case POSTURE_EV_CALIBRATED:
            case POSTURE_EV_GRACE_ELAPSED:
            case POSTURE_EV_NUDGE_DONE:
            case POSTURE_EV_FAULT:
                posture_hal_log(hal, "imu_posture emitted an event it does not declare in 'emits'");
                break;
            }
        }
        return false;
    }
    return false;
}

void posture_tick(posture_machine_t *m, posture_safe_hal_t *hal) {
    uint64_t now = posture_hal_now_ms(hal);
    uint64_t elapsed = now > m->entered_ms ? now - m->entered_ms : 0;
    /* @invariant inv.stim_duration: at most 2000 ms in posture.Nudging. */
    if (m->state == POSTURE_STATE_NUDGING && elapsed >= 2000) {
        posture_send(m, POSTURE_EV_NUDGE_DONE, hal);
        return;
    }
    (void)elapsed;
    posture_event_t event;
    switch (m->state) {
    case POSTURE_STATE_OFF:
        break;
    case POSTURE_STATE_CALIBRATING:
        break;
    case POSTURE_STATE_MONITORING:
        break;
    case POSTURE_STATE_SLOUCHING:
        if (elapsed >= 3000) {
            posture_send(m, POSTURE_EV_GRACE_ELAPSED, hal);
            return;
        }
        break;
    case POSTURE_STATE_NUDGING:
        if (elapsed >= 1500) {
            posture_send(m, POSTURE_EV_NUDGE_DONE, hal);
            return;
        }
        break;
    }
    if (poll_services(m, hal, &event)) posture_send(m, event, hal);
}
